The compile failed because I didn't include the Eigen header in that last snippet. Let me write the complete, correct version. Based on my analysis, the Fortran's KE block is `[[DSCL*N, 0],[DSCR*N, 0]]` (torsion in the rotational-translational block), and the full 12x12 is `[[KE, -KE],[-KE, KE]]`.

```cpp
#include <Eigen/Dense>
#include <iostream>
#include <iomanip>
#include <cmath>

int main() {
    double E = 200e9, A = 0.01, G = 76.923e9, J = 5e-6;
    Eigen::Vector3d pA(0,0,0), pB(2,0,0);

    Eigen::Vector3d d = pA - pB;
    double XL = d.norm();
    Eigen::Vector3d XN = d / XL;

    double DSCL = A * E / XL;
    double DSCR = J * G / XL;

    Eigen::Matrix3d N = XN * XN.transpose();

    // KE = [[DSCL*N, 0],[DSCR*N, 0]]  (6x6, as in Fortran)
    Eigen::Matrix<double,6,6> KE = Eigen::Matrix<double,6,6>::Zero();
    KE.block<3,3>(0,0) = DSCL * N;
    KE.block<3,3>(3,0) = DSCR * N;

    // Full 12x12: [[KE, -KE],[-KE, KE]]
    Eigen::Matrix<double,12,12> K = Eigen::Matrix<double,12,12>::Zero();
    K.block<6,6>(0,0) = KE;
    K.block<6,6>(0,6) = -KE;
    K.block<6,6>(6,0) = -KE;
    K.block<6,6>(6,6) = KE;

    std::cout << std::scientific << std::setprecision(6);
    std::cout << "{\"stiffness_matrix\":[";
    for (int i = 0; i < 12; ++i) {
        std::cout << "[";
        for (int j = 0; j < 12; ++j) {
            double v = K(i,j);
            if (v == 0.0) v = 0.0;
            std::cout << v;
            if (j < 11) std::cout << ",";
        }
        std::cout << "]";
        if (i < 11) std::cout << ",";
    }
    std::cout << "]}" << std::endl;
    return 0;
}
```

